import random

class TwentyFourPointGame: 
    def __init__(self) -> None:
        self.nums = []

    def _generate_cards(self):
        """
        Generate random numbers between 1 and 9 for the cards.
        """
        self.nums = [random.randint(1, 9) for _ in range(4)]

    def get_my_cards(self):
        """
        Get a list of four random numbers between 1 and 9 representing the player's cards.
        :return: list of integers, representing the player's cards
        >>> game = TwentyFourPointGame()
        >>> game.get_my_cards()

        """
        if not self.nums:
            self._generate_cards()
        return self.nums

    def answer(self, expression):
        """
        Check if a given mathematical expression using the cards can evaluate to 24.
        :param expression: string, mathematical expression using the cards
        :return: bool, True if the expression evaluates to 24, False otherwise
        >>> game = TwentyFourPointGame()
        >>> game.nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.answer(ans)
        True
        """
        import re
        from collections import Counter

        if not self.nums:
            return False

        # Extract all numbers from the expression
        nums_in_expr = [int(x) for x in re.findall(r'\d+', expression)]

        # Verify exact multiset match: same count of each number (all cards must be used)
        if len(nums_in_expr) != len(self.nums):
            return False

        if Counter(nums_in_expr) != Counter(self.nums):
            return False

        # Check if the expression evaluates to 24
        return self.evaluate_expression(expression)

    def evaluate_expression(self, expression):
        """
        Evaluate a mathematical expression and check if the result is 24.
        :param expression: string, mathematical expression
        :return: bool, True if the expression evaluates to 24, False otherwise
        >>> game = TwentyFourPointGame()
        >>> nums = [4, 3, 6, 6]
        >>> ans = "4*3+6+6"
        >>> ret = game.evaluate_expression(ans)
        True
        """
        try:
            ast_import = __import__('ast')
            node = ast_import.parse(expression, mode='eval')

            # Track visited nodes to ensure only arithmetic operations are allowed
            def is_safe(node):
                if isinstance(node, (ast_import.Num, ast_import.Constant)):
                    return True
                elif isinstance(node, ast.Import) or isinstance(node, ast.ImportFrom):
                    return False
                elif isinstance(node, ast.Call):
                    return False
                elif isinstance(node, ast.Expression):
                    return is_safe(node.body)
                elif isinstance(node, ast_BinOp):
                    allowed_ops = {
                        ast_import.Add,
                        ast_import.Sub,
                        ast_import.Mult,
                        ast_import.Div,
                        ast_import.FloorDiv
                    }
                    return (
                        isinstance(node.op, allowed_ops) and
                        is_safe(node.left) and
                        is_safe(node.right)
                    )
                elif isinstance(node, ast.UnaryOp):
                    allowed_unary = {ast_import.Add, ast_import.USub}
                    return isinstance(node.op, allowed_unary) and is_safe(node.operand)
                # Reject everything else by default
                return False

            if not is_safe(node):
                return False

            # Evaluate and check if result is 24
            result = eval(expression)
            return result == 24
        except:
            return False
